package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.history.HistoryListener;

/** A claim made by a person on a sheet: an amount, a date, a note and its status. */
@Entity
@EntityListeners(HistoryListener.class)
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 15, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    /** The date the claim is due by: fixed when it is created, its date plus its person's own
     *  terms, else the terms of their grade in force on that date, else the sheet's then; later
     *  changes to the terms or its date leave it. A holiday added on or before it re-fixes it (while
     *  the claim is neither SETTLED nor VOID) from its date with {@link #terms}. */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The terms (business days) the claim's due-by was fixed with. */
    @Column(name = "terms", nullable = false)
    private int terms;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The sheet's number for the claim, given when it is opened and kept if it is voided; none
     *  while DRAFT. A sheet-wide number (1, 2, ...), or under period numbering one within its
     *  period (<period name>-<n>, X-<n> in no period). */
    @Column(name = "claim_number")
    private String number;

    /** The due fixed when the claim was settled; none before then, or when its grade had no rate
     *  (its due then stays live). */
    @Column(name = "settled_due", precision = 15, scale = 2)
    private BigDecimal settledDue;

    /** The user who opened the claim; none while DRAFT. That user cannot settle it. */
    @Column(name = "opened_by")
    private String openedBy;

    /** The user who last edited the claim; none until edited. Like its opener, that user cannot
     *  settle or approve it. */
    @Column(name = "edited_by")
    private String editedBy;

    /** The number of the bulk settle that settled the claim (or sent it to PENDING); none when
     *  it was settled one at a time or not at all. */
    @Column(name = "batch")
    private Integer batch;

    /** Whether the person's last statement bound the claim (it counted then); its due then stays
     *  {@link #statedDue} until their next statement. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The due the claim showed at the statement that bound it; none while unbound, or when it was
     *  n/a then. */
    @Column(name = "stated_due", precision = 15, scale = 2)
    private BigDecimal statedDue;

    /** The number of the SETTLED claim of the same person that this correction (a negative
     *  amount) corrects; none for any other claim. */
    @Column(name = "corrects")
    private String corrects;

    /** Where the claim is listed, newest (highest) first: the sheet's next when it is added or
     *  reassigned to another person. */
    @Column(name = "listed", nullable = false)
    private long listed;

    /** The date an OPEN claim is deferred until; none when it was never deferred. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** How many proofs the claim has; 0 until the first is added. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** The number of the claim this one was split from; none for a claim not made by a split. */
    @Column(name = "split_from")
    private String splitFrom;

    /** The user whose open editor locks the claim for everyone else; none while unlocked. */
    @Column(name = "locked_by")
    private String lockedBy;

    /** Whether the claim was added while its period was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** The last day (the sheet's today then) a reminder was written for the claim; none when never
     *  reminded. */
    @Column(name = "reminded")
    private LocalDate reminded;

    /** The claim's external reference, unique on its sheet without regard to case; none when not
     *  given. */
    @Column(name = "ref")
    private String ref;

    /** The claim's tags: lower-case, sorted and comma separated, without repeats; none when it has
     *  none. */
    @Column(name = "tags")
    private String tags;

    /** The reason a VOID claim was voided with, from its sheet's list; none when not given. */
    @Column(name = "void_reason")
    private String voidReason;

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.dueBy = dueBy;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** Move the claim to another person. */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public long getListed() {
        return listed;
    }

    public void setListed(long listed) {
        this.listed = listed;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    /** Whether the claim is a correction: its amount is negative. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public void setDueBy(LocalDate dueBy) {
        this.dueBy = dueBy;
    }

    public int getTerms() {
        return terms;
    }

    public void setTerms(int terms) {
        this.terms = terms;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public String getEditedBy() {
        return editedBy;
    }

    public void setEditedBy(String editedBy) {
        this.editedBy = editedBy;
    }

    public Integer getBatch() {
        return batch;
    }

    public void setBatch(Integer batch) {
        this.batch = batch;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void setDeferredUntil(LocalDate deferredUntil) {
        this.deferredUntil = deferredUntil;
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    public void setSplitFrom(String splitFrom) {
        this.splitFrom = splitFrom;
    }

    public String getLockedBy() {
        return lockedBy;
    }

    public void setLockedBy(String lockedBy) {
        this.lockedBy = lockedBy;
    }

    public boolean isLateEntry() {
        return lateEntry;
    }

    public void setLateEntry(boolean lateEntry) {
        this.lateEntry = lateEntry;
    }

    public LocalDate getReminded() {
        return reminded;
    }

    public void setReminded(LocalDate reminded) {
        this.reminded = reminded;
    }

    public String getRef() {
        return ref;
    }

    public void setRef(String ref) {
        this.ref = ref;
    }

    public String getTags() {
        return tags;
    }

    public void setTags(String tags) {
        this.tags = tags;
    }

    public String getVoidReason() {
        return voidReason;
    }

    public void setVoidReason(String voidReason) {
        this.voidReason = voidReason;
    }

    /** A copy of the claim for a person on another sheet, as a transfer carries it: its amount,
     *  dates, terms, note, status, frozen settled figure, opener and editor, deferral, proofs, tags
     *  and the rest of its own values. Its number, batch, reference, statement binding, lock and
     *  listing are left for the other sheet to give; corrects and split-from name this sheet's
     *  numbers, so the caller maps them. */
    public Claim transferredTo(String sheetId, Long personId) {
        Claim copy = new Claim(sheetId, personId, amount, date, dueBy, note);
        copy.terms = terms;
        copy.status = status;
        copy.settledDue = settledDue;
        copy.openedBy = openedBy;
        copy.editedBy = editedBy;
        copy.corrects = corrects;
        copy.deferredUntil = deferredUntil;
        copy.proofs = proofs;
        copy.splitFrom = splitFrom;
        copy.lateEntry = lateEntry;
        copy.reminded = reminded;
        copy.tags = tags;
        copy.voidReason = voidReason;
        return copy;
    }

    /** A copy of the claim for a clone of the sheet: what a transfer carries, and its reference,
     *  batch and listing too. Its number and statement binding are left for the clone to give, and
     *  it is not locked; corrects and split-from name this sheet's numbers, so the caller maps them. */
    public Claim clonedTo(String sheetId, Long personId) {
        Claim copy = transferredTo(sheetId, personId);
        copy.ref = ref;
        copy.batch = batch;
        copy.listed = listed;
        return copy;
    }

    /** Whether another user than this one holds the claim's editor open. */
    public boolean isLockedFor(String user) {
        return lockedBy != null && !lockedBy.equals(user);
    }

    public int getProofs() {
        return proofs;
    }

    /** Set how many proofs the claim has: only for a version rebuilt from the sheet's history. */
    public void setProofs(int proofs) {
        this.proofs = proofs;
    }

    /** Add a proof to the claim. */
    public void addProof() {
        proofs++;
    }

    /** Whether the claim is deferred on a date: OPEN, deferred until a date after it. Until then it
     *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && deferredUntil.isAfter(today);
    }

    /** Whether the claim's due is bound to {@link #statedDue}: it is stated and not PENDING (a
     *  PENDING claim shows its live figure, and is bound again if rejected back to OPEN). */
    public boolean isBound() {
        return stated && status != ClaimStatus.PENDING;
    }

    /** Bind the claim to a due (null: n/a) until the person's next statement. */
    public void bind(BigDecimal due) {
        this.stated = true;
        this.statedDue = due;
    }

    /** Leave the claim unbound, its due live again. */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
    }
}
package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Optional;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * The sheet's rounding policy: a claim dated before the policy date rounds half up, one dated on
 * or after it half to even. It decides every rounding of the claim's live figures (the rate step
 * and the late charge); a correction rounds by the date of the claim it corrects.
 */
public record Rounding(LocalDate policyDate) {

    /** The rounding of a sheet as it is now; a sheet never loaded takes today as its policy date. */
    public static Rounding of(Optional<Sheet> sheet) {
        return new Rounding(sheet.map(Sheet::getPolicyDateInForce).orElseGet(LocalDate::now));
    }

    /** How a claim whose rounding date is {@code date} rounds. */
    public RoundingMode on(LocalDate date) {
        return date.isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Optional;
import java.util.function.BiFunction;
import java.util.function.Function;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * The sheet's late charge: an OPEN (or PENDING) claim overdue (its late-from, its due-by, fixed when it was created,
 * plus the grace days in force on its date of its person's grade then, before the sheet's today) gains, for every full
 * 30 days it is overdue, the late percent in force on that boundary date (its late-from plus 30, 60, 90 ... days) of
 * its figure plus the charges of the boundaries before it (compounding), each rounded as the claim's rounding policy
 * has it, added up on top; a correction (a negative amount) gains none. It is never bound by a statement; settling freezes it in.
 */
public record LateCharge(LocalDate today, Function<LocalDate, BigDecimal> pctOn,
        BiFunction<String, LocalDate, Integer> graceOn) {

    /** The days in each step of the charge. */
    private static final int STEP_DAYS = 30;

    /** The late charge of a sheet as it is now, at the late percent in force on each boundary date;
     *  a sheet never loaded charges nothing. */
    public static LateCharge of(Optional<Sheet> sheet) {
        return new LateCharge(sheet.map(Sheet::getToday).orElseGet(LocalDate::now),
                on -> sheet.map(s -> s.latePctOn(on)).orElse(Sheet.DEFAULT_LATE_PCT),
                (grade, on) -> sheet.map(s -> s.graceOn(grade, on)).orElse(0));
    }

    /** The date the claim is overdue after: its due-by plus the grace days in force on its date of
     *  its person's grade then (none: its due-by). */
    public LocalDate lateFrom(Claim claim, Person person) {
        return claim.getDueBy().plusDays(graceOn.apply(person.gradeOn(claim.getDate()), claim.getDate()));
    }

    /** Whether the claim's late-from is before the sheet's today (whatever its status). */
    public boolean isPast(Claim claim, Person person) {
        return lateFrom(claim, person).isBefore(today);
    }

    /** The claim's figure (null: n/a, which stays n/a) with its late charge, rounded by {@code mode}, added. */
    public BigDecimal addTo(Claim claim, Person person, BigDecimal figure, RoundingMode mode) {
        if (!claim.getStatus().isOpen() || claim.isDeferredOn(today)) {
            return figure;
        }
        return addToOpen(claim, person, figure, mode);
    }

    /** The figure with the late charge the claim would gain were it open, whatever its status. */
    public BigDecimal addToOpen(Claim claim, Person person, BigDecimal figure, RoundingMode mode) {
        if (figure == null || claim.isCorrection()) {
            return figure;
        }
        LocalDate lateFrom = lateFrom(claim, person);
        long overdue = ChronoUnit.DAYS.between(lateFrom, today);
        if (overdue <= 0) {
            return figure;
        }
        BigDecimal charged = figure;
        for (long step = 1; step <= overdue / STEP_DAYS; step++) {
            BigDecimal pct = pctOn.apply(lateFrom.plusDays(step * STEP_DAYS));
            if (pct.signum() != 0) {
                charged = charged.add(charged.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode));
            }
        }
        return charged;
    }
}
package net.officefloor.hq.app.claim;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Set;

/** Counting business days: every day but a Saturday, a Sunday or one of the sheet's holidays. */
public final class BusinessDays {

    private BusinessDays() {
    }

    /** Whether {@code day} is a business day. */
    public static boolean isBusinessDay(LocalDate day, Set<LocalDate> holidays) {
        DayOfWeek dow = day.getDayOfWeek();
        return dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY && !holidays.contains(day);
    }

    /** The {@code count}-th business day after {@code from}, counting forward from the day after
     *  it; {@code from} itself when {@code count} is 0. */
    public static LocalDate after(LocalDate from, int count, Set<LocalDate> holidays) {
        LocalDate day = from;
        for (int left = count; left > 0; ) {
            day = day.plusDays(1);
            if (isBusinessDay(day, holidays)) {
                left--;
            }
        }
        return day;
    }
}
package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a clerk settling one whose due is
 *  above the clerk limit sends it to PENDING instead, which a steward approves (SETTLED) or rejects
 *  (back to OPEN). A DRAFT, OPEN or PENDING claim may be VOID, and a steward may void a SETTLED one
 *  within {@link #SETTLED_VOID_DAYS} days of its settlement. A DRAFT claim may be DELETED, when it
 *  counts nowhere, and restored to DRAFT on the sheet's today it was deleted. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED;

    /** How many days after its settlement (by the sheet's today) a steward may still void a SETTLED claim. */
    public static final int SETTLED_VOID_DAYS = 7;

    /** Whether a claim in this status may move to the given status. */
    public boolean canMoveTo(ClaimStatus to) {
        return switch (to) {
            case OPEN -> this == DRAFT || this == PENDING;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN || this == PENDING;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED;
            case DRAFT -> this == DELETED;
            case DELETED -> this == DRAFT;
        };
    }

    /** Whether a claim in this status is open: OPEN, or PENDING (handled like an OPEN one). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}

