271	     *  while set, else its today.
272	     *  Refused (409) once the claim is no longer a DRAFT (an open claim is voided and a new one
273	     *  added instead), and (423) when its due-by (which the edit leaves) is in a closed period, and (422) when the new
274	     *  date is after the person's retirement date, or when it is a correction that does not name
275	     *  the number of a SETTLED claim of the same person, and (422) when it has lines and the amount is
276	     *  not their total, and (409) when its reference (blank: none) is
277	     *  used by another claim on the sheet, comparing without regard to case. Its tags are
278	     *  replaced as {@link #tagsOf} has them. */
279	    @Transactional
280	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
281	            String corrects, String ref, String tags) {
282	        Claim claim = claims.findForUpdate(id, sheetId)
283	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
284	        LocalDate on = date != null ? date : sheets.entryDate(sheetId);
285	        refuseIfClosed(sheetId, claim.getDueBy());
286	        if (claim.getStatus() != ClaimStatus.DRAFT) {
287	            throw new ResponseStatusException(HttpStatus.CONFLICT,
288	                    "A " + claim.getStatus() + " claim cannot be edited");
289	        }
290	        refuseIfLocked(claim, user);
291	        BigDecimal lined = linesTotal(claim.getId());
292	        if (lined != null && lined.compareTo(amount) != 0) {
293	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
294	                    "A claim with lines has their total as its amount");
295	        }
296	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
297	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
298	        refuseIfRetired(person, on);
299	        String corrected = correctedBy(sheetId, person.getId(), amount, corrects);
300	        String reference = refOf(sheetId, claim.getId(), ref);
301	        RollupService.Snapshot before = rollup.snapshot(sheetId);
302	        claim.setAmount(amount);
303	        claim.setCorrects(corrected);
304	        claim.setRef(reference);
305	        claim.setTags(tagsOf(tags));
306	        claim.setDate(on);
307	        claim.setNote(noteOf(note));
308	        claim.setLockedBy(null);
309	        claim.setEditedBy(user);
310	        claims.flush();
311	        keepTags(claim);
312	        record("CLAIM_EDITED", user, person, claim);
313	        rollup.recordChanges(sheetId, user, before);
314	        return claim;
315	    }
