367	    /** Settle the claims (in the order given) as {@link #changeStatus} does, all or nothing, as the
368	     *  sheet's next batch: each claim carries the batch's number, a claim sent to PENDING counts in
369	     *  it, and BATCH_SETTLED follows the claims' own records with the batch's count and the total of
370	     *  the frozen figures of those SETTLED. Any refusal refuses the whole batch, leaving every claim
371	     *  as it was and recording nothing. */
372	    @Transactional
373	    public void settleBatch(String sheetId, String user, List<Long> ids) {
374	        if (ids.isEmpty()) {
375	            return;
376	        }
377	        int number = claims.findLastBatch(sheetId) + 1;
378	        BigDecimal total = BigDecimal.ZERO.setScale(2);
379	        for (long id : ids) {
380	            Claim claim = changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null);
381	            claim.setBatch(number);
382	            claims.save(claim);
383	            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
384	                total = total.add(claim.getSettledDue());
385	            }
386	        }
387	        claims.flush();
388	        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + number
389	                + " count=" + ids.size() + " total=" + total.setScale(2).toPlainString());
390	    }
