392	    /** Void a claim as {@link #changeStatus} does, with a reason from the sheet's list of void
393	     *  reasons (null: none): while the list is not empty, a void without one of them is refused
394	     *  (422), and a reason given while it is empty is refused too. The VOIDED record ends with it. */
395	    @Transactional
396	    public Claim voidClaim(String sheetId, String user, long id, String reason) {
397	        return changeStatus(sheetId, user, id, ClaimStatus.VOID, reason);
398	    }
