400	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus to, String voidReason) {
401	        Claim claim = claims.findForUpdate(id, sheetId)
402	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
403	        refuseIfClosed(sheetId, claim.getDueBy());
404	        switch (to) {
405	            case OPEN -> settings.refuseUnlessAllowed(sheetId, user, Permission.OPEN);
406	            case SETTLED -> settings.refuseUnlessAllowed(sheetId, user, Permission.SETTLE);
407	            case VOID -> settings.refuseUnlessAllowed(sheetId, user, Permission.VOID);
408	            default -> {
409	            }
410	        }
411	        if (to == ClaimStatus.PENDING || (to == ClaimStatus.SETTLED && claim.getStatus() == ClaimStatus.PENDING)
412	                || !claim.getStatus().canMoveTo(to)) {
413	            throw new ResponseStatusException(HttpStatus.CONFLICT,
414	                    "A " + claim.getStatus() + " claim cannot become " + to);
415	        }
416	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
417	            refuseUnlessVoidableSettled(sheetId, user, claim);
418	        }
419	        if (to == ClaimStatus.VOID) {
420	            refuseUnlessListedReason(sheetId, voidReason);
421	        }
422	        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
423	            throw new ResponseStatusException(HttpStatus.CONFLICT,
424	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
425	        }
426	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
427	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
428	                    "The user who opened a claim cannot settle it");
429	        }
430	        if (to == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
431	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
432	                    "The user who last edited a claim cannot settle it");
433	        }
434	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
435	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
436	        if (to == ClaimStatus.OPEN) {
437	            refuseIfNoteless(claim, shownDueOf(claim, person));
438	            refuseIfOverCap(sheetId, claim);
439	        }
440	        // a claim bound by a statement settles at its bound figure, its late charge frozen in
441	        BigDecimal settling = to == ClaimStatus.SETTLED ? shownDueOf(claim, person) : null;
442	        if (to == ClaimStatus.SETTLED) {
443	            // before the clerk limit: a claim needing a proof never goes to PENDING
444	            refuseIfUnproven(claim, person, settling);
445	        }
446	        if (to == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, settling)) {
447	            // above the clerk limit: a steward approves or rejects it
448	            to = ClaimStatus.PENDING;
449	        }
450	        RollupService.Snapshot before = rollup.snapshot(sheetId);
451	        // a voided claim keeps its number (never reused), and the VOIDED record carries it
452	        String number = claim.getNumber();
453	        // a voided SETTLED claim keeps its frozen figure, which leaves every total
454	        boolean reversing = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
455	        BigDecimal reversed = claim.getSettledDue();
456	        claim.setStatus(to);
457	        if (to == ClaimStatus.OPEN) {
458	            number = nextNumber(sheetId, claim.getDueBy());
459	            claim.setNumber(number);
460	            claim.setOpenedBy(user);
461	        } else if (to == ClaimStatus.SETTLED) {
462	            claim.setSettledDue(settling);
463	        } else if (to == ClaimStatus.VOID) {
464	            claim.setVoidReason(voidReason);
465	        }
466	        claims.flush();
467	        logStatus(user, person, claim);
468	        String event = switch (to) {
469	            case OPEN -> "CLAIM_OPENED";
470	            case PENDING -> "CLAIM_PENDING";
471	            case SETTLED -> "CLAIM_SETTLED";
472	            case VOID -> "CLAIM_VOIDED";
473	            case DRAFT, DELETED -> throw new IllegalArgumentException("A claim is deleted and restored on its own");
474	        };
475	        if (to == ClaimStatus.SETTLED) {
476	            record(event, user, person, claim, number, " due=" + dueText(claim.getSettledDue()));
477	            notifyWatchers(user, person, number);
478	        } else if (to == ClaimStatus.VOID) {
479	            record(event, user, person, claim, number, (reversing ? " reversed=" + dueText(reversed) : "")
480	                    + (voidReason != null ? " reason=" + voidReason : ""));
481	        } else {
482	            record(event, user, person, claim, number);
483	        }
484	        rollup.recordChanges(sheetId, user, before);
485	        return claim;
486	    }
