488	    /** Delete a DRAFT claim: it becomes DELETED, counting nowhere, its log gains a DELETED line
489	     *  and CLAIM_DELETED is written. Refused (404) when missing, (423) when due in a closed
490	     *  period, (409) unless a DRAFT, and (409) while another user holds its editor open. */
491	    @Transactional
492	    public Claim delete(String sheetId, String user, long id) {
493	        Claim claim = claims.findForUpdate(id, sheetId)
494	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
495	        refuseIfClosed(sheetId, claim.getDueBy());
496	        if (!claim.getStatus().canMoveTo(ClaimStatus.DELETED)) {
497	            throw new ResponseStatusException(HttpStatus.CONFLICT,
498	                    "Only a DRAFT claim is deleted, not a " + claim.getStatus() + " one");
499	        }
500	        refuseIfLocked(claim, user);
501	        return moveDeleted(sheetId, user, claim, ClaimStatus.DELETED, "CLAIM_DELETED");
502	    }
