504	    /** Restore a DELETED claim to DRAFT on the sheet's today it was deleted (its last DELETED log
505	     *  line): its log gains a DRAFT line and CLAIM_RESTORED is written. Refused (404) when missing,
506	     *  (423) when due in a closed period, (409) unless DELETED, and (409) on a later day. */
507	    @Transactional
508	    public Claim restore(String sheetId, String user, long id) {
509	        Claim claim = claims.findForUpdate(id, sheetId)
510	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
511	        refuseIfClosed(sheetId, claim.getDueBy());
512	        if (!claim.getStatus().canMoveTo(ClaimStatus.DRAFT)) {
513	            throw new ResponseStatusException(HttpStatus.CONFLICT,
514	                    "Only a DELETED claim is restored, not a " + claim.getStatus() + " one");
515	        }
516	        LocalDate deletedOn = log.findByClaimIdOrderByIdAsc(claim.getId()).stream()
517	                .filter(line -> line.getStatus() == ClaimStatus.DELETED)
518	                .map(ClaimLog::getOn)
519	                .reduce((first, second) -> second)
520	                .orElse(null);
521	        if (!sheets.today(sheetId).equals(deletedOn)) {
522	            throw new ResponseStatusException(HttpStatus.CONFLICT,
523	                    "A claim is restored only on the day it was deleted");
524	        }
525	        return moveDeleted(sheetId, user, claim, ClaimStatus.DRAFT, "CLAIM_RESTORED");
526	    }
