528	    private Claim moveDeleted(String sheetId, String user, Claim claim, ClaimStatus to, String event) {
529	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
530	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
531	        RollupService.Snapshot before = rollup.snapshot(sheetId);
532	        claim.setStatus(to);
533	        claim.setLockedBy(null);
534	        claims.flush();
535	        logStatus(user, person, claim);
536	        record(event, user, person, claim);
537	        rollup.recordChanges(sheetId, user, before);
538	        return claim;
539	    }
