542	     *  empty, and with a reason not on it. */
543	    private void refuseUnlessListedReason(String sheetId, String reason) {
544	        if (reason == null ? !settings.voidReasons(sheetId).isEmpty() : !settings.isVoidReason(sheetId, reason)) {
545	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
546	                    "Choose a reason from the sheet's list to void the claim");
547	        }
