550	    /** Refuse voiding a SETTLED claim (403) by anyone but a steward, and (409) once the sheet's
551	     *  today is more than {@link ClaimStatus#SETTLED_VOID_DAYS} days after its settlement (the
552	     *  first SETTLED line of its status log). */
553	    private void refuseUnlessVoidableSettled(String sheetId, String user, Claim claim) {
554	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
555	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a SETTLED claim");
556	        }
557	        LocalDate settledOn = log.findByClaimIdOrderByIdAsc(claim.getId()).stream()
558	                .filter(line -> line.getStatus() == ClaimStatus.SETTLED)
559	                .map(ClaimLog::getOn)
560	                .findFirst()
561	                .orElse(null);
562	        LocalDate today = sheets.today(sheetId);
563	        if (settledOn == null || today.isAfter(settledOn.plusDays(ClaimStatus.SETTLED_VOID_DAYS))) {
564	            throw new ResponseStatusException(HttpStatus.CONFLICT,
565	                    "A SETTLED claim is voided only within " + ClaimStatus.SETTLED_VOID_DAYS + " days of its settlement");
566	        }
567	    }
