569	    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches
570	     *  it, the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
571	     *  statement. Refused (404) when missing, (423) when due in a closed period, (409) unless
572	     *  OPEN, and (422) when the date is not after the sheet's today. */
573	    @Transactional
574	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
575	        Claim claim = claims.findForUpdate(id, sheetId)
576	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
577	        refuseIfClosed(sheetId, claim.getDueBy());
578	        if (claim.getStatus() != ClaimStatus.OPEN) {
579	            throw new ResponseStatusException(HttpStatus.CONFLICT,
580	                    "Only an OPEN claim is deferred, not a " + claim.getStatus() + " one");
581	        }
582	        if (!until.isAfter(sheets.today(sheetId))) {
583	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
584	                    "A claim is deferred until a date after the sheet's today");
585	        }
586	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
587	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
588	        RollupService.Snapshot before = rollup.snapshot(sheetId);
589	        claim.setDeferredUntil(until);
590	        claims.flush();
591	        record("CLAIM_DEFERRED", user, person, claim, claim.getNumber(), " until=" + until);
592	        rollup.recordChanges(sheetId, user, before);
593	        return claim;
594	    }
