596	    /** Remind an OPEN or PENDING claim: REMIND is written and the claim's reminded date becomes
597	     *  the sheet's today. Refused (404) when missing, (409) unless OPEN or PENDING, and (409) when
598	     *  it was already reminded on the sheet's today. */
599	    @Transactional
600	    public Claim remind(String sheetId, String user, long id) {
601	        Claim claim = claims.findForUpdate(id, sheetId)
602	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
603	        if (!claim.getStatus().isOpen()) {
604	            throw new ResponseStatusException(HttpStatus.CONFLICT,
605	                    "Only an OPEN or PENDING claim is reminded, not a " + claim.getStatus() + " one");
606	        }
607	        LocalDate today = sheets.today(sheetId);
608	        if (today.equals(claim.getReminded())) {
609	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded on " + today);
610	        }
611	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
612	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
613	        claim.setReminded(today);
614	        claims.flush();
615	        record("REMIND", user, person, claim, claim.getNumber());
616	        return claim;
617	    }
