619	    /** A steward re-dates an OPEN or PENDING claim: its due-by stays as it was fixed, a figure a
620	     *  statement bound it to stays bound, and so does its period (that of its due-by) and its
621	     *  number. Refused (404) when missing, (403) for anyone but a steward, (423) when its due-by
622	     *  is in a closed period, (409) unless OPEN or PENDING, and (422) when the new date is after
623	     *  the person's retirement date. */
624	    @Transactional
625	    public Claim redate(String sheetId, String user, long id, LocalDate date) {
626	        Claim claim = claims.findForUpdate(id, sheetId)
627	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
628	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
629	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-dates a claim");
630	        }
631	        refuseIfClosed(sheetId, claim.getDueBy());
632	        if (!claim.getStatus().isOpen()) {
633	            throw new ResponseStatusException(HttpStatus.CONFLICT,
634	                    "Only an OPEN or PENDING claim is re-dated, not a " + claim.getStatus() + " one");
635	        }
636	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
637	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
638	        refuseIfRetired(person, date);
639	        RollupService.Snapshot before = rollup.snapshot(sheetId);
640	        LocalDate old = claim.getDate();
641	        claim.setDate(date);
642	        claims.flush();
643	        record("CLAIM_REDATED", user, person, claim, claim.getNumber(), " old=" + old + " new=" + date);
644	        rollup.recordChanges(sheetId, user, before);
645	        return claim;
646	    }
