648	    /** A steward approves a PENDING claim: it becomes SETTLED, its due (its live figure, with its
649	     *  late charge) frozen now. Refused (409) unless PENDING, (403) for a clerk or the user who
650	     *  opened or last edited it, (423) when it is due in a closed period, and (422) when its due is above the
651	     *  proof threshold in force on its date while it has no proof. */
652	    @Transactional
653	    public Claim approve(String sheetId, String user, long id) {
654	        Claim claim = pendingForSteward(sheetId, user, id);
655	        if (user.equals(claim.getOpenedBy())) {
656	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
657	                    "The user who opened a claim cannot approve it");
658	        }
659	        if (user.equals(claim.getEditedBy())) {
660	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
661	                    "The user who last edited a claim cannot approve it");
662	        }
663	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
664	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
665	        BigDecimal due = shownDueOf(claim, person);
666	        refuseIfUnproven(claim, person, due);
667	        RollupService.Snapshot before = rollup.snapshot(sheetId);
668	        claim.setStatus(ClaimStatus.SETTLED);
669	        claim.setSettledDue(due);
670	        claims.flush();
671	        logStatus(user, person, claim);
672	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), " due=" + dueText(due));
673	        notifyWatchers(user, person, claim.getNumber());
674	        rollup.recordChanges(sheetId, user, before);
675	        return claim;
676	    }
