905	     *  that counts (OPEN, PENDING or SETTLED, but no unbound open one within a hold, nor a deferred one) to its figure now; the others
906	     *  are left unbound. Taken as of a date ({@code asOf}, not null), the sheet as it stood at the end
907	     *  of that date stands in for it now (see {@link #statementAsOf}). */
908	    @Transactional
909	    public Statement statement(String sheetId, String user, long personId, LocalDate asOf) {
910	        if (asOf != null) {
911	            return statementAsOf(sheetId, user, personId, asOf);
912	        }
913	        Person person = people.findForUpdate(personId, sheetId)
914	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
915	        LocalDate today = sheets.today(sheetId);
