919	        BigDecimal dueTotal = Sheet.capped(dueTotalOf(counted, person, today), sheets.cap(sheetId));
920	        for (Claim c : theirs) {
921	            if (counts(c, person, today)) {
922	                // the statement binds the figure; the late charge keeps following the sheet's today
923	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
924	            } else {
