935	     *  standing in for the sheet's today in every figure; their other claims are left unbound.
936	     *  Refused (422) when the date is after the sheet's today, or the person was not yet added then. */
937	    private Statement statementAsOf(String sheetId, String user, long personId, LocalDate asOf) {
938	        Person person = people.findForUpdate(personId, sheetId)
939	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
940	        LocalDate today = sheets.today(sheetId);
941	        if (asOf.isAfter(today)) {
942	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
943	                    "A statement is taken as of a date on or before the sheet's today");
944	        }
945	        HistoryService.AsOf then = history.asOf(sheetId, asOf);
946	        Person was = then.people().get(personId);
947	        if (was == null) {
948	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
949	                    "The person was not yet on the sheet on " + asOf);
950	        }
951	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
952	        RollupService.Snapshot before = rollup.snapshot(sheetId);
953	        RollupService.Stated stated = RollupService.statedOn(then.sheet(), was, personId,
954	                List.copyOf(then.claims().values()), RateChain.flatten(sheetId, then.rates(),
955	                        rateChain.ancestors(sheetId).stream().map(a -> history.asOf(a, asOf).rates()).toList()));
956	        Map<Long, BigDecimal> bound = new HashMap<>();
957	        then.claims().forEach((id, c) -> {
958	            if (stated.counted().containsKey(c)) {
959	                bound.put(id, stated.counted().get(c));
960	            }
961	        });
962	        for (Claim c : theirs) {
963	            if (bound.containsKey(c.getId())) {
964	                c.bind(bound.get(c.getId()));
965	            } else {
966	                c.unbind();
967	            }
968	        }
969	        claims.flush();
970	        return stated(sheetId, user, person, theirs, stated.dueTotal(), stated.counted().size(), today, asOf, before);
971	    }
