1035	        for (Claim c : claims.findBySheetIdForUpdate(sheetId)) {
1036	            if (c.getStatus() == ClaimStatus.SETTLED || c.getStatus() == ClaimStatus.VOID
1037	                    || c.getStatus() == ClaimStatus.DELETED || c.getDueBy().isBefore(added.day())) {
1038	                continue;
1039	            }
1040	            c.setDueBy(BusinessDays.after(c.getDate(), c.getTerms(), holidays));
