1046	    /** The number a claim due by {@code date} takes as it is opened: under period numbering (set,
1047	     *  and the sheet's today on or after it) the next within the period containing the due-by
1048	     *  (<period name>-<n>), or X-<n> when none does; otherwise the sheet's next number within the
1049	     *  fiscal year of the due-by (FY<yyyy>-<n>). */
1050	    public String nextNumber(String sheetId, LocalDate date) {
1051	        if (!sheets.periodNumberingOn(sheetId)) {
1052	            return sheets.nextFiscalClaimNumber(sheetId, date);
1053	        }
1054	        // held until the transaction ends, so two claims opened at once are numbered one after the other
1055	        sheets.lock(sheetId);
1056	        String prefix = periods.containing(sheetId, date).map(Period::getName).orElse(NO_PERIOD) + "-";
1057	        List<String> given = new ArrayList<>(claims.findNumbers(sheetId));
1058	        given.addAll(retired.findNumbers(sheetId));
1059	        int last = given.stream()
1060	                .filter(n -> n.startsWith(prefix))
1061	                .map(n -> n.substring(prefix.length()))
1062	                .filter(n -> n.matches("\\d{1,9}"))
1063	                .mapToInt(Integer::parseInt)
1064	                .max().orElse(0);
1065	        return prefix + (last + 1);
1066	    }
