410	   *  person's retirement date reached on the sheet's today. */
411	  private readonly leftOut = computed(() => {
412	    const holds = this.holdsById();
413	    const retired = this.retiredFromById();
414	    const today = this.session.today();
415	    return (c: Claim) => {
416	      const from = retired.get(c.personId);
417	      return heldOn(holds.get(c.personId) ?? [], c.date) || (from !== undefined && today !== null && from <= today);
418	    };
419	  });
420	  /** Whether a claim counts in the live totals: open (OPEN or PENDING) and SETTLED ones, but not a deferred one,
421	   *  nor an open one dated within a hold of its person, or of a person whose retirement date is reached,
422	   *  unless bound by a statement. */
423	  private readonly countsLive = computed(() => {
424	    const leftOut = this.leftOut();
425	    const today = this.session.today();
426	    return (c: Claim) => counts(c, today) && !(isOpen(c) && !isBound(c) && leftOut(c));
427	  });
428	  /** The ids of the people who are active: with an open (OPEN or PENDING) claim that counts in the
429	   *  live totals, dated within the 30 days up to and including the sheet's today. */
430	  protected readonly activeIds = computed(() => {
431	    const today = this.session.today();
432	    const out = new Set<number>();
433	    if (today === null) return out;
434	    const since = plusDays(today, -29);
435	    const live = this.countsLive();
436	    for (const c of this.claims()) {
437	      if (isOpen(c) && live(c) && since <= c.date && c.date <= today) out.add(c.personId);
438	    }
439	    return out;
440	  });
441	  /** Each person's claims (newest first) and claimed in cents (counting claims only, corrections left out), by person id. */
442	  private readonly byPerson = computed(() => {
443	    const out = new Map<number, { claims: Claim[]; cents: number }>();
444	    const live = this.countsLive();
445	    for (const c of this.claims()) {
446	      const entry = out.get(c.personId) ?? { claims: [], cents: 0 };
447	      entry.claims.push(c);
448	      if (live(c) && !c.corrects) entry.cents += cents(c.amount);
449	      out.set(c.personId, entry);
450	    }
451	    return out;
452	  });
453	  /** The sheet's rates (a percent with two decimals), each for a grade from a from-date. */
454	  protected readonly rates = signal<Rate[]>([]);
455	  /** The rates of each of the sheet's ancestors, its parent's first. */
456	  private readonly inherited = signal<Rate[][]>([]);
457	  /** The rates in force on the sheet: its own, else (for a grade and date with none) its ancestors'. */
458	  protected readonly effectiveRates = computed(() => effectiveRates(this.rates(), this.inherited()));
459	  /** What every late charge follows: the sheet's today and late percent. */
460	  private readonly lateness = computed<Lateness>(() => ({
461	    today: this.session.today(), latePctOn: (d) => this.session.latePctOn(d),
462	  }));
463	  /** Each person's due-total in cents, by person id: the sum of the dues their OPEN and SETTLED
464	   *  claims show (each already rounded; open ones within a hold, unbound, left out). Null (n/a) when their grade in force on the
465	   *  sheet's today has no rate then, unless a claim shows a due (a settled claim's fixed one, a stated claim's bound one,
466	   *  or one at the rate of the grade they had on its date): then the sum of the dues there are. */
467	  private readonly uncappedDueByPerson = computed(() => {
468	    const out = new Map<number, number | null>();
469	    const late = this.lateness();
470	    for (const p of this.people()) {
471	      const dues = this.claimsOf(p.id).filter(this.countsLive())
472	        .map((c) => this.claimDueCents(p, c, late))
473	        .filter((d): d is number => d !== null);
474	      if (pctOn(this.ratesOf(this.gradeOf(p)), this.session.today()) === null && dues.length === 0) {
475	        out.set(p.id, null);
476	        continue;
477	      }
478	      out.set(p.id, dues.reduce((sum, d) => sum + d, 0));
479	    }
480	    return out;
481	  });
482	  /** Each person's due-total in cents, by person id, held to the sheet's cap: the cap when their
483	   *  uncapped one is above it (n/a is not capped). */
484	  private readonly dueByPerson = computed(() => {
485	    const cap = this.session.cap();
486	    const capCents = cap === null ? null : cents(cap);
487	    const out = new Map<number, number | null>();
488	    for (const [id, due] of this.uncappedDueByPerson()) {
489	      out.set(id, due === null || capCents === null ? due : Math.min(due, capCents));
490	    }
491	    return out;
492	  });
493	  /** Each person's uncapped due-total split in cents, by person id: the dues (n/a ones skipped) their
494	   *  counting SETTLED claims show (at their fixed figures) and those their counting open (OPEN and
495	   *  PENDING) claims show. */
496	  private readonly settledOpenByPerson = computed(() => {
497	    const out = new Map<number, { settled: number; open: number }>();
498	    const late = this.lateness();
499	    for (const p of this.people()) {
500	      const split = { settled: 0, open: 0 };
501	      for (const c of this.claimsOf(p.id).filter(this.countsLive())) {
502	        const due = this.claimDueCents(p, c, late) ?? 0;
503	        if (c.status === 'SETTLED') split.settled += due;
504	        else if (isOpen(c)) split.open += due;
505	      }
506	      out.set(p.id, split);
507	    }
508	    return out;
509	  });
