527	  /** Each person's overdue claims, by person id: how many of their counting claims are overdue
528	   *  (OPEN with the due-by before the sheet's today), and the dues they show in cents (n/a ones skipped). */
529	  private readonly overdueByPerson = computed(() => {
530	    const out = new Map<number, { count: number; cents: number }>();
531	    const late = this.lateness();
532	    for (const p of this.people()) {
533	      const overdueClaims = this.claimsOf(p.id).filter(this.countsLive()).filter((c) => overdue(c, late.today, this.graceOf(p, c)));
534	      out.set(p.id, {
535	        count: overdueClaims.length,
536	        cents: overdueClaims.reduce((sum, c) => sum + (this.claimDueCents(p, c, late) ?? 0), 0),
