541	  /** Each person's open (OPEN and PENDING) counting claims' dues in cents (n/a ones skipped), by person id,
542	   *  split by the claim's age on the sheet's today (days from its date): 0 to 30, 31 to 60, 61 or more;
543	   *  one dated after today counts as 0 to 30. */
544	  private readonly agedByPerson = computed(() => {
545	    const out = new Map<number, Aged>();
546	    const late = this.lateness();
547	    const today = late.today;
548	    const from31 = today === null ? null : plusDays(today, -31);
549	    const from61 = today === null ? null : plusDays(today, -61);
550	    for (const p of this.people()) {
551	      const aged: Aged = { upTo30: 0, upTo60: 0, over60: 0 };
552	      for (const c of this.claimsOf(p.id).filter(this.countsLive()).filter(isOpen)) {
553	        const due = this.claimDueCents(p, c, late) ?? 0;
554	        if (from61 !== null && c.date <= from61) aged.over60 += due;
555	        else if (from31 !== null && c.date <= from31) aged.upTo60 += due;
556	        else aged.upTo30 += due;
557	      }
558	      out.set(p.id, aged);
559	    }
