574	   *  the end of the period's last day: as the live totals count it in that status (one not yet
575	   *  added then does not count). */
576	  private readonly countsAtEnd = computed(() => {
577	    const leftOut = this.leftOut();
578	    const today = this.session.today();
579	    return (c: Claim, end: string) => {
580	      const status = statusOn(c, end);
581	      if (status === null) return false;
582	      if (status === 'SETTLED') return true;
583	      if ((status !== 'OPEN' && status !== 'PENDING') || deferred(c, today)) return false;
584	      // a hold or a reached retirement leaves out a claim still open now, as the live due-total does
585	      return !isOpen(c) || isBound(c) || !leftOut(c);
