588	  /** Each person's live due-total for each period in cents, by person id then period id: the dues
589	   *  (n/a ones skipped) of their claims whose due-by falls in it, each counted by its status at the
590	   *  period's end (OPEN and SETTLED ones; ones still open within a hold, unbound, or deferred, left out). */
591	  private readonly liveDueByPersonPeriod = computed(() => {
592	    const out = new Map<number, Map<number, number>>();
593	    const late = this.lateness();
594	    const countsAtEnd = this.countsAtEnd();
595	    for (const p of this.people()) {
